for a in "--bogus g1alpha" "-s BOGUS g1alpha" "-s 0 g1alpha" "-999 g1alpha" ""; do out=$(killall $a 2>&1); rc=$?; echo "usage[$a] rc=$rc diagnostic=$([[ -n $out ]] && echo yes || echo no)"; done
