mk c g1beta 61
pid=${PID[c]}; ppid=; uid=; comm=
while IFS= read -r l; do case $l in PPid:*) ppid=${l#PPid:};; Uid:*) set -- ${l#Uid:}; uid=$1;; Name:*) comm=${l#Name:};; esac; done < /proc/$pid/status
echo "before ppid-is-shell=$([[ $((ppid)) == $$ ]] && echo yes || echo no) uid=$uid comm=$(echo $comm)"
killall -USR1 g1beta 2>&1 | norm; echo "rc=${PIPESTATUS[0]}"
settle c; wait $pid; echo "wait=$?"
echo "alive-after=$([[ -d /proc/$pid ]] && echo yes || echo no)"

